/**
 * @name Server-Side Request Forgery via URL manipulation
 * @description User-controlled URLs used in HTTP requests without validation may allow SSRF attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/httpcore-ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Looking for socket.connect, socket operations with addresses
      call = API::moduleImport("socket").getMember("socket").getReturn().getMember("connect").getACall() and
      sink = call.getArg(0)
      or
      // HTTP request methods that take URLs
      exists(DataFlow::AttrRead attr |
        attr.getAttributeName() in ["request", "handle_request", "handle_async_request"] and
        call.getFunction() = attr and
        sink = call.getArg(0)
      )
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF: user-controlled data flows to network request $@.", source, "from user input"

/**
 * @name HTTP Header Injection via CRLF
 * @description Detects potential HTTP header injection through unsanitized CRLF characters
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Headers being set in httpcore
      call.getFunction().asExpr().(Attribute).getName() in ["add", "append", "extend", "update", "setdefault"] and
      sink = call.getArg(_)
    )
  }

  predicate isBarrier(DataFlow::Node node) {
    // If CRLF characters are sanitized
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asExpr().(Attribute).getName() in ["replace", "strip"] and
      node = call
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential HTTP header injection from $@.", source.getNode(), "user input"
